                native._focus_bound_origin(turn.task_id,str(meta.origin),'otp')
                if native._current_page_origin(turn.task_id)!=meta.origin:
                    raise AccessError('The verification page does not match this saved account.',403)
                code=service.store.consume_code(team=turn.source.scope_id,owner=turn.source.user_id,
                    home=service.private_home(turn.source.scope_id,turn.source.user_id),
                    task_id=turn.task_id,handle=access.handle,origin=meta.origin)
                if access.grant_id or access.home!=turn.home:
                    from agent.vault_store import totp_now
                    secret=access.secret()
                    code=totp_now(secret['otp_secret']) if secret.get('otp_secret') else code
                    if not code:
                        return json.dumps(service.call(service.request_code(turn,meta,access=access)))
                    with service.lock_for(access.home):
                        return service.delegations.fill_local(turn,access,code=code)
                result=native.browser_vault_enter_code(meta.id,task_id=turn.task_id,
                    expected_origin=meta.origin,provided_code=code)
                del code
                if json.loads(result).get('error_type')=='prompt_unavailable':
                    return json.dumps(service.call(service.request_code(turn,meta)))
                return result
        raise AccessError('This credential operation is unavailable.')
    except AccessError as error:
        return json.dumps({'success':False,'error':str(error),'status':error.status})
    except Exception:
        return json.dumps({'success':False,'error':'The credential operation could not complete. No secret has been returned.'})


def register_tools(ctx):
    definitions = {
        'clanker_request_access':(
            'Request a private hosted credential form. For website logins, use kind login while the actual HTTPS login page is open. For API keys, use kind api_key, a service-specific label for the form title, and the exact HTTPS API origin; no browser is required. Shared-channel tasks use isolated requester-owned execution; the login link is sent to DM and the final requested result returns to the original thread. Never ask for credentials in chat, local key files or environment variables. The handler sends the link; saving resumes the task automatically.',
            {'kind':{'type':'string','enum':['login','api_key'],'default':'login'},'login_method':{'type':'string','enum':['auto','password','sms'],'default':'auto','description':'Use sms for phone-number + SMS-code login. Local auto detects a phone-only first step. Use password if a password follows the phone number. Collect phone numbers privately, never supply them as identifier.'},'label':{'type':'string','description':'Form title supplied by this request. Required for API keys; identify the service and credential being collected.','maxLength':120},'origin':{'type':'string','description':'Required only for API keys: exact HTTPS API origin, with no path, query, fragment or embedded credentials.'},'identifier':{'type':'string','description':'Known email or username for password login forms only. Never a phone number, password or API key.'}},[]),
        'clanker_vault_list':('List this requester\'s own and explicitly invited login, card and API-key handles and metadata. Invited handles can be used on the owner\'s behalf, never reshared. Shared requests start isolated execution with a private login detour and reply to the original thread. Secret values are never returned.',{},[]),
        'clanker_api_request':('Call the exact HTTPS service bound to an owned or invited API-key handle. The backend adds authentication; never supply the key in the task, path, body or headers. Redirects and host-local destinations are refused. This can perform external changes: use only for the user\'s requested operation; check outcomes before retrying.',
            {'handle':{'type':'string'},'path':{'type':'string','description':'Relative path and optional query beginning with one slash.'},
             'method':{'type':'string','enum':['GET','POST','PUT','PATCH','DELETE','HEAD'],'default':'GET'},
             'body':{'description':'Optional JSON request body.'},'headers':{'type':'object','additionalProperties':{'type':'string'}},
             'auth_header':{'type':'string','enum':['Authorization','x-api-key','X-API-Key','api-key'],'default':'Authorization'},
             'auth_scheme':{'type':'string','enum':['Bearer',''],'default':'Bearer'}},['handle','path']),
        'clanker_request_payment':('Request an owner-only card and purchase approval form for the current local checkout. The backend captures its actual origin and checkout contents. Specify the exact merchant, items/quantities and final total including fees. Optional handle selects a saved card. No card details enter chat. Shared requests move to DM. End the turn while waiting; approval resumes it. Cloud browsers cannot receive card data.',
            {'checkout_url':{'type':'string','description':'Exact URL of the open HTTPS checkout tab in the private local browser.'},
             'merchant':{'type':'string','maxLength':120},'summary':{'type':'string','maxLength':1000},
             'amount_minor':{'type':'integer','description':'Final total including fees, in minor units: INR 699.00 is 69900 paise.'},
             'currency':{'type':'string','enum':['INR','USD','EUR','GBP','CAD','AUD'],'default':'INR'},
             'handle':{'type':'string','description':'Optional private saved-card handle for this checkout origin.'}},['checkout_url','merchant','summary','amount_minor']),
        'clanker_pay':('Execute the owner-approved purchase in the original local supervised checkout. The backend checks owner, conversation, browser, page contents and payment button and consumes approval before card fill and submission. Each purchase needs fresh approval; unknown outcomes cannot be replayed. A submitted result is not proof of payment: verify the merchant receipt. Bank approval may still need the owner.',
            {'request_id':{'type':'string'}},['request_id']),
        'clanker_vault_fill':('Fill a saved password or SMS-login phone number into this task\'s browser on its exact permitted origin. For SMS logins, never type the masked identifier; this tool fills the private number. Then request the website\'s SMS code and use clanker_vault_enter_code. Password logins: type the metadata username first. No secret is returned.',{'handle':{'type':'string'}},['handle']),
        'clanker_vault_enter_code':('Enter an authenticator or current SMS/email verification code on the saved login origin, including passwordless SMS logins. Without a setup key, send a private hosted one-time-code form and resume automatically after submission. Each SMS login requires a fresh code; never ask for it in chat. No code or setup key is returned.',{'handle':{'type':'string'}},['handle']),
    }
    for name,(description,properties,required) in definitions.items():
        schema={'name':name,'description':description,'parameters':{'type':'object','properties':properties,'required':required,'additionalProperties':False}}
        ctx.register_tool(name,'clanker_browser',schema,lambda args,_name=name,**kwargs:execute(_name,args,**kwargs),description=description,emoji='🔐')

