    if(location.pathname==='/vault'){
      const result=await api('/api/items',{});csrf=result.csrf;el('title').textContent='Your vault';document.title='Your vault · clanker';el('description').textContent='Manage your saved credentials and access shared with you.';el('items').hidden=false;
      renderVaultItems(result.items);el('vault-actions').hidden=false;el('vault-sharing').hidden=false;await refreshInvitations();return;
    }
    if(!access)throw new Error('Open the secure access link clanker sent you in Slack.');
    const result=await api('/api/request',access);csrf=result.csrf;el('title').textContent=result.label;
    el('description').textContent='Give clanker access to '+new URL(result.origin).hostname+'.';el('identifier').value=result.identifier;
    if(result.kind==='code'){el('description').textContent='Enter the current '+(result.login_method==='sms'?'SMS ':'verification ')+'code for '+new URL(result.origin).hostname+'.';el('code-form').hidden=false;}
    else if(result.kind==='api_key'){el('description').textContent='Give clanker access to '+result.label+'.';el('api-key-form').hidden=false;}
    else if(result.kind==='payment'){
      const payment=result.payment,order=payment.order,total=order.currency+' '+(order.amount_minor/100).toFixed(2);
      el('description').textContent='Review this purchase on '+new URL(result.origin).hostname+'.';
      el('payment-merchant').textContent=order.merchant;el('payment-summary').textContent=order.summary;el('payment-total').textContent=total;
      if(payment.requested_by)el('description').textContent=payment.requested_by+' requested this purchase using your shared card. Review and approve it privately.';
      el('payment-checkout').textContent=payment.checkout_text;el('payment-button').textContent='Clanker will press: '+payment.payment_button;
      el('payment-consent').textContent='I approve one payment of '+total+' to '+order.merchant+' for this purchase.';
      savedCard=Boolean(payment.saved_card);el('payment-new-fields').hidden=savedCard;
      el('title').textContent=savedCard?'Approve payment':'Card details';document.title=el('title').textContent+' · clanker';
      for(const id of ['card-number','card-month','card-year'])el(id).required=!savedCard;
      if(savedCard){el('saved-card').textContent=payment.saved_card.label+' · ending '+payment.saved_card.last4;el('saved-card').hidden=false;}
      el('save-payment').textContent=(savedCard?'Approve ':'Save card and approve ')+total+' →';el('payment-form').hidden=false;
    }
    else if(result.kind==='login'&&result.login_method==='sms'){el('description').textContent='Connect your phone number to sign in to '+new URL(result.origin).hostname+'.';el('phone-form').hidden=false;}
    else if(result.kind==='login')el('form').hidden=false;
    else throw new Error('This access request uses an unsupported form. Ask Clanker for a new link.');
  }catch(error){if((error.status===401 || error.status===403) && (access || location.pathname==='/vault')){el('description').textContent=error.status===403?error.message:'Sign in with Slack to open your private vault.';el('signin').hidden=false;}else fail(error);}
}
