            assert response.status==403
            for fields in ({'REDACTED':'REDACTED'},{'api_key':'REDACTED','origin':'https://evil.invalid'},{'api_key':''}):
                response=await client.post('/api/api-key',json=data|{'fields':fields},headers=headers)
                assert response.status==400
            key='CLANKER_REDACTED_API_KEY_'+str(index)
