def classify_checkout_control(control: LoginControl) -> Optional[ClassifiedLoginControl]:
    """Classify one control as a payment/address fill target (autocomplete token exact match 100,
    label/name heuristic 70), or None. Password/email inputs are never checkout targets."""
    tokens = [t for t in control.autocomplete.lower().split() if t]
    for token in PAYMENT_AUTOFILL_TOKENS + ADDRESS_AUTOFILL_TOKENS:
        if token in tokens:
            return ClassifiedLoginControl(control, 100, "country-name" if token == "country" else token)
    if control.type in ("password", "email"):
        return None
    searchable = _normalize_text(" ".join(part for part in (control.name, control.label) if part))
    for pattern, token in _CHECKOUT_HEURISTICS:
        if pattern.search(searchable):
            return ClassifiedLoginControl(control, 70, token)
    return None


def select_checkout_fills(classified: List[ClassifiedLoginControl], secret: Dict[str, str],
                          field_tokens: Dict[str, str]) -> List[Dict[str, Any]]:
    """Map a payment/address secret payload onto the best control per autocomplete token.

    ``field_tokens`` is ``PAYMENT_FIELDS`` / ``ADDRESS_FIELDS`` (agent/vault_store.py). A combined
    ``cc-exp`` control gets ``MM/YY`` from exp_month + exp_year and then suppresses the separate
    month/year fills. Returns ``[{"index", "token", "value"}]``: one control per token, highest
    score then DOM order.
    """
    values: Dict[str, str] = {tok: secret[f] for f, tok in field_tokens.items() if secret.get(f)}
    if "cc-exp-month" in values and "cc-exp-year" in values:
        values["cc-exp"] = f"{values['cc-exp-month'].zfill(2)}/{values['cc-exp-year'][-2:]}"
    fills: List[Dict[str, Any]] = []
    for token, value in values.items():
        candidates = sorted((c for c in classified if c.token == token), key=lambda c: (-c.score, c.control.index))
        if candidates:
            fills.append({"index": candidates[0].control.index, "token": token, "value": value})
    if any(f["token"] == "cc-exp" for f in fills):
        fills = [f for f in fills if f["token"] not in ("cc-exp-month", "cc-exp-year")]
    return fills


# JS expression evaluated in the page to inspect candidate input controls.
# Ported from OpenInstinct's nativeLoginControlInspectionExpression.
# Inspection stamps every input with ``<nonce>:<index>`` under a per-inspection attribute; the fill
# script resolves targets by the stamp of ITS OWN inspection instead of re-querying by position, so
# neither a DOM reflow nor a second inspection in between can redirect the password into another field.
INSPECTION_STAMP_ATTR = "data-hermes-vault-slot"


def build_otp_fills(otp_controls: List[ClassifiedLoginControl], code: str) -> List[Dict[str, Any]]:
    """One fill per box. Default: the single best-scoring code field takes the whole code.

    Per-digit entry only when the page unmistakably uses it: exactly len(code) OTP controls that are all
    ``maxlength=1``, all in the same form, and adjacent in DOM order (the classic N-box widget). Anything
    looser (several code-like inputs scattered over a page) gets ONE field, never a digit sprayed across
    unrelated inputs."""
    best = max(otp_controls, key=lambda c: c.score)
    boxes = sorted((c for c in otp_controls if c.control.max_length == 1), key=lambda c: c.control.index)
    if (len(boxes) == len(code)
            and len({b.control.form_index for b in boxes}) == 1
            and all(b.control.index - a.control.index == 1 for a, b in zip(boxes, boxes[1:]))):
        return [{"index": b.control.index, "token": "one-time-code", "value": ch} for b, ch in zip(boxes, code)]
    return [{"index": best.control.index, "token": "one-time-code", "value": code}]


def build_inspection_js(nonce: str) -> str:
    return _LOGIN_CONTROL_INSPECTION_JS_TEMPLATE.replace("__NONCE__", json.dumps(nonce))


_LOGIN_CONTROL_INSPECTION_JS_TEMPLATE = """(() => {
  const nonce = __NONCE__;
  const elements = Array.from(document.querySelectorAll("input, select"));
  const forms = Array.from(document.forms);
  elements.forEach((element, index) => element.setAttribute("data-hermes-vault-slot", nonce + ":" + index));
  const out = elements.flatMap((element, index) => {
    if (element.disabled || element.readOnly) return [];
    if (["hidden", "submit", "button", "reset", "file", "image", "checkbox", "radio"].includes(element.type)) return [];
    const style = getComputedStyle(element);
    if (style.display === "none" || style.visibility === "hidden" || element.getClientRects().length === 0) return [];
    const labels = element.labels ? Array.from(element.labels, (l) => l.textContent || "") : [];
    const ariaText = (element.getAttribute("aria-labelledby") || "")
      .split(/\\s+/).filter(Boolean)
      .map((id) => { const n = document.getElementById(id); return n ? (n.textContent || "") : ""; })
      .join(" ");
    const resolvedFormIndex = element.form ? forms.indexOf(element.form) : -1;
    return [{
      autocomplete: element.autocomplete || "",
      formIndex: resolvedFormIndex >= 0 ? resolvedFormIndex : null,
      index,
      maxLength: element.maxLength > 0 ? element.maxLength : null,
      label: [
        ...labels,
        element.getAttribute("aria-label") || "",
        ariaText,
        element.getAttribute("placeholder") || "",
        element.getAttribute("title") || "",
      ].join(" "),
      name: [element.name, element.id].join(" "),
      type: element.tagName === "SELECT" ? "select" : (element.type || ""),
    }];
  });
  return JSON.stringify(out);
})()"""


def build_fill_js(fills: List[Dict[str, Any]], expected_origin: str, nonce: str = "") -> str:
    """Build a JS expression that fills the selected controls and reports only a count. The
    returned expression never echoes the values back.

    ``expected_origin`` is asserted against ``window.location.origin`` synchronously inside the SAME
    evaluated script, immediately before any write. If the page navigated between inspection and fill
    (TOCTOU), the script writes nothing and returns ``{"refused": "origin_changed", "found": <actual>}``:
    proof scope equals mutation scope (#88706). Targets resolve by the ``<nonce>:<index>`` stamp of
    THIS inspection; a ``current-password`` fill additionally requires ``type=password``; ``<select>``
    controls (country, state, expiry month) match an option by value or visible text. No marker is
    left on filled controls so later model-driven DOM reads cannot address them deterministically.
    """
    payload = json.dumps(
        [{"index": f["index"], "token": f.get("token", "current-password"), "value": f["value"]} for f in fills]
    )
    return (_FILL_JS_TEMPLATE.replace("__EXPECTED_ORIGIN__", json.dumps(expected_origin))
            .replace("__FILLS__", payload).replace("__NONCE__", json.dumps(nonce)))


_FILL_JS_TEMPLATE = """(() => {
  const expectedOrigin = __EXPECTED_ORIGIN__;
  if (window.location.origin !== expectedOrigin) {
    return JSON.stringify({ refused: "origin_changed", found: window.location.origin });
  }
  const fills = __FILLS__;
  const nonce = __NONCE__;
  let filled = 0;
  const norm = (t) => String(t || "").trim().toLowerCase();
  for (const f of fills) {
    const el = document.querySelector('[data-hermes-vault-slot="' + nonce + ':' + f.index + '"]');
    if (!el || (f.token === "current-password" && el.type !== "password")) continue;
    try {
      if (el.tagName === "SELECT") {
        const want = norm(f.value);
        const opt = Array.from(el.options).find((o) => [o.value, o.textContent].some((t) => norm(t) === want || norm(t) === want.replace(/^0/, "")));
        if (opt) { el.value = opt.value; el.dispatchEvent(new Event("change", { bubbles: true })); filled += 1; }
        continue;
      }
      el.focus();
      const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value");
      // one-time-code split into single-character boxes: f.value is the slice for THIS box (see build_otp_fills)
      if (setter && setter.set) { setter.set.call(el, f.value); } else { el.value = f.value; }
      el.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText" }));
      el.dispatchEvent(new Event("change", { bubbles: true }));
      if (el.value.length > 0) filled += 1;
    } catch (e) { /* skip */ }
  }
  document.querySelectorAll("[data-hermes-vault-slot]").forEach((n) => n.removeAttribute("data-hermes-vault-slot"));
  return JSON.stringify({ filled });
})()"""
"""Private vault handles -> run-scoped Browser Use secrets, through Composio.

Models supply goals and local session names, never provider IDs or credential
values. Provider IDs live in the protected gateway directory. Browser state is
keyed by the authenticated conversation context, never a model-supplied owner.
"""
import hashlib
import json
from pathlib import Path
import re
from urllib.parse import urlsplit

from vault.store import AccessError
from .client import ComposioBrowserClient, ComposioBrowserToolClient

TERMINAL = {'completed', 'failed', 'cancelled'}
from vault.login import LOGIN_FIELDS, OTP_FIELDS, PHONE_FIELDS


def configured(vault_service):
    path = vault_service.policy.home / '.clanker-cloud' / 'config.json'
    if not path.exists():
        return None
    settings = json.loads(path.read_text())
    if not settings.get('enabled'):
        return None
    if settings.get('provider') == 'browser_tool':
        fields = {'enabled', 'provider', 'organization_id', 'project_id', 'connection_user_id', 'tool_version'}
        if set(settings) != fields or not all(isinstance(settings[k], str) and settings[k]
                for k in fields - {'enabled'}):
            raise AccessError('The consumer browser connection is incomplete.', 503)
        from agent.secret_scope import build_profile_secret_scope
        key = build_profile_secret_scope(vault_service.policy.home).get('CLANKER_COMPOSIO_USER_API_KEY')
        if not key:
            raise AccessError('Authorize the Composio consumer account before enabling Browser Tool.', 503)
        from .browser_tool import BrowserTool
        return BrowserTool(vault_service, settings, ComposioBrowserToolClient(settings, key))
    if set(settings) != {'enabled', 'connected_account_id', 'connection_user_id', 'tool_version', 'max_cost_usd'}:
        raise AccessError('The cloud browser configuration has unsupported fields.', 503)
    if not all(isinstance(settings[k], str) and settings[k] for k in ('connected_account_id', 'connection_user_id', 'tool_version')):
        raise AccessError('The cloud browser connection is incomplete.', 503)
    if isinstance(settings['max_cost_usd'], bool) or not 0 < float(settings['max_cost_usd']) <= 100:
        raise AccessError('The cloud browser requires a positive per-run cost limit.', 503)
    from agent.secret_scope import build_profile_secret_scope
    key = build_profile_secret_scope(vault_service.policy.home).get('CLANKER_COMPOSIO_API_KEY')
    if not key:
        raise AccessError('Configure the Composio project key before enabling the cloud browser.', 503)
    return CloudBrowser(vault_service, settings, ComposioBrowserClient(settings, key))


class CloudBrowser:
    profile_retained_on_stop = True
    def __init__(self, vault_service, settings, client):
        self.vault = vault_service
        self.settings = settings
        self.client = client
        self.directory = vault_service.policy.home / '.clanker-cloud'

    def context_key(self, turn):
        self.vault.validate_member(turn.source.scope_id, turn.source.user_id)
        if not self.vault.policy.authorize_source(turn.source):
            raise AccessError('This browser context is not authorized.', 403)
        return hashlib.sha256(('v2:' + turn.source.scope_id + ':' + turn.source.user_id + ':' + str(turn.home.resolve())).encode()).hexdigest()

    def owned_state(self, turn, path):
        owner = {'team': turn.source.scope_id, 'requester': turn.source.user_id}
        state = json.loads(path.read_text()) if path.exists() else {'owner': owner, 'sessions': {}, 'threads': {}}
        if state.get('owner') != owner:
            raise AccessError('The browser state has no verified requester ownership.', 403)
        return state

    def claim_session(self, turn, session_id):
        owner = (turn.source.scope_id, turn.source.user_id, self.context_key(turn))
        provider = type(self).__name__
        with self.vault.store.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            row = db.execute('SELECT team,requester,context FROM browser_session_owners WHERE provider=? AND session_id=?',
                             (provider, session_id)).fetchone()
            if row and tuple(row) != owner:
                raise AccessError('The provider returned a browser assigned to another requester. This task is quarantined.', 403)
            db.execute('INSERT OR IGNORE INTO browser_session_owners VALUES (?,?,?,?,?)',
                       (provider, session_id, *owner))

    def check_access(self, turn, entry):
        if entry.get('cleanup_pending'):
            raise AccessError('Browser cookie cleanup has not been verified. This account context remains blocked.', 403)
        self.vault.delegations.check_execution(turn)
        if entry.get('access_handle'):
            self.vault.delegations.resolve(turn, entry['access_handle'])

    def bind_access(self, turn, access):
        self.vault.delegations.resolve(turn, access.handle)
        self.vault.delegations.check_execution(turn)
        path, state = self.state(turn)
        _, entry = self.selected(turn, state)
        if entry.get('access_handle') not in (None, access.handle):
            raise AccessError('This browser is bound to another credential. Stop it before opening a different account.', 403)
        entry['access_handle'] = access.handle
        self.save(path, state)
        self.vault.delegations.record_browser_use(turn, access)

    def state(self, turn):
        key = self.context_key(turn)
        path = self.directory / 'contexts' / (key + '.json')
        return path, self.owned_state(turn, path)

    def save(self, path, state):
        from seatbelt.install import write
        write(path, json.dumps(state, indent=2) + '\n')

    def thread(self, turn):
        return turn.source.chat_id + ':' + str(turn.source.thread_id or '')

    def selected(self, turn, state, session=None):
        name = session or state['threads'].get(self.thread(turn))
        if not name or name not in state['sessions']:
            raise AccessError('Start or select this thread\'s cloud browser before using saved access.', 409)
        return name, state['sessions'][name]

    def execute(self, name, args):
        return self.client.execute('BROWSER_USE_' + name, args)

    def safe_result(self, turn, data):
        from agent.vault_store import VaultStore, scrub_secret_from_text
        text = str(data.get('result') or '')
        # Scrub every saved secret in this private context, including credentials
        # supplied on an earlier run. Never return raw provider responses.
        store = VaultStore(self.vault.private_home(turn.source.scope_id,turn.source.user_id) / 'vault')
        for meta in store.list_items():
            text = scrub_secret_from_text(text, store.resolve_secret(meta.id))
        # Preserve output scrubbing for one-time codes across gateway restarts.
        # Only encrypted values are persisted in the protected context record.
        _, state = self.state(turn)
        cipher = self.vault.store.code_crypto()
        for entry in state['sessions'].values():
            for encrypted in entry.get('redactions', []):
                text = scrub_secret_from_text(text, {'value': cipher.decrypt(encrypted.encode()).decode()})
        from agent.redact import redact_sensitive_text, redact_registered_vault_values
        text = redact_registered_vault_values(redact_sensitive_text(text,force=True))
        return {'status': data.get('status'), 'result': text,
                'success': data.get('status') == 'completed',
                'result_verified': False}

    def status(self, turn, session=None):
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            name, entry = self.selected(turn, state, session)
            self.check_access(turn, entry)
            if entry.get('dispatch_unknown'):
                raise AccessError('A previous dispatch was not acknowledged. The operator must reconcile it before another run.', 409)
            if not entry.get('run_id'):
                return {'status': 'idle', 'session': name}
            data = self.execute('GET_RUN_STATUS', {'run_id': entry['run_id']})
            entry['status'] = data['status']
            self.save(path, state)
            if data['status'] in TERMINAL:
                data = self.execute('GET_RUN', {'run_id': entry['run_id']})
            return {'session': name, **self.safe_result(turn, data)}

    def start(self, turn, task, session='web', *, bindings=None):
        if not isinstance(task, str) or not task.strip() or len(task) > 20000:
            raise AccessError('Supply a browser task of at most 20,000 characters.')
        if not isinstance(session, str) or not re.fullmatch(r'[a-z0-9][a-z0-9_-]{0,39}', session):
            raise AccessError('Use a short lowercase browser session name.')
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            entry = state['sessions'].setdefault(session, {})
            self.check_access(turn, entry)
            if entry.get('dispatch_unknown'):
                raise AccessError('A previous dispatch was not acknowledged. Ask the operator to reconcile it.', 409)
            if entry.get('run_id'):
                current = self.execute('GET_RUN_STATUS', {'run_id': entry['run_id']})
                if current['status'] not in TERMINAL:
                    return {'status': current['status'], 'session': session,
                            'next': 'Use clanker_browser_status; the existing run is still active.'}
            state['threads'][self.thread(turn)] = session
            entry['dispatch_unknown'] = True
            self.save(path, state)
            if not entry.get('profile_id'):
                profile = self.execute('CREATE_PROFILE', {'name': 'clanker-' + session,
                    'user_id': self.context_key(turn)})
                entry['profile_id'] = profile['id']
                self.save(path, state)
            args = {'task': task, 'agentmail': False,
                    'browser_settings': {'profileId': entry['profile_id'], 'record': False},
                    'max_cost_usd': self.settings['max_cost_usd']}
            if entry.get('session_id'):
                args['session_id'] = entry['session_id']
            if bindings:
                # Only trusted fill/code handlers can construct this argument.
                self.vault.assert_private(turn)
                args['secret_bindings'] = bindings
                cipher = self.vault.store.code_crypto()
                entry['redactions'] = (entry.get('redactions', []) + [
                    cipher.encrypt(item['source']['value'].encode()).decode() for item in bindings
                ])[-64:]
                self.save(path,state)
            run = self.execute('START_RUN', args)
            self.claim_session(turn, run['sessionId'])
            entry.update(run_id=run['id'], session_id=run['sessionId'],
                         status=run['status'], dispatch_unknown=False)
            entry.pop('browser_id', None)
            self.save(path, state)
            return {'status': run['status'], 'session': session,
                    'next': 'Use clanker_browser_status until this run ends. Verify the reported website result before claiming success.'}

