declare const tools: { mcp__lunagraph__canvas_add(args: {
  // For ROOT insertions: the element this new frame relates to — the user's selection, an @-referenced element, or the frame you are making a variation of. Any element id works; the editor uses its top-level frame. The new root lands in the nearest free slot beside that frame. Ignored when parent_id, x, or y is set.
  anchor_id?: string;
  // Optional active canvas page ID. If provided, it must be the currently active/open canvas page.
  canvas_id?: string;
  // claim_id from canvas_claim on the parent. Required when parent_id is set; optional for root insertions (locks new elements when provided).
  claim_id?: string;
  // For a new root shell, add and immediately claim the created root in this call. Returns the claim_id. Do not combine with parent_id or claim_id.
  claim_new?: boolean;
  // JSX code for the new element(s)
  jsx: string;
  // Parent element ID to add inside (optional, adds to root if omitted)
  parent_id?: string;
  // Optional X position in canvas pixels for ROOT insertions only. Ignored when parent_id is set. Omit this unless you have a specific coordinate — prefer anchor_id so the editor places the root beside related work. Do not pass 100/100 (or any overlap) when the page already has work on it.
  x?: number;
  // Optional Y position in canvas pixels for ROOT insertions only. Ignored when parent_id is set. Omit with x so auto-placement can align to existing frames.
  y?: number;
}): Promise<CallToolResult>; };
