1	"use client";
2	import React from "react";
3	import { Search, ChevronDown, Check, X, ShieldCheck, KeyRound, CreditCard, LockKeyhole, ArrowRight, ArrowLeft, UserPlus } from "lucide-react";
4	export const colors = { ink:"#171717", muted:"#686868", line:"#e7e7e7", soft:"#f5f5f5", selected:"#f2f3f2", green:"#26704d" };
5	export const type = { fontFamily:"Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif" };
6	export const icons = { Search, ChevronDown, Check, X, ShieldCheck, KeyRound, CreditCard, LockKeyhole, ArrowRight, ArrowLeft, UserPlus };
7	interface ButtonProps { children?: React.ReactNode; variant?: "primary" | "secondary" | "ghost" | "destructive"; disabled?: boolean; onClick?: ()=>void; fullWidth?: boolean; compact?: boolean; }
8	export function VaultButton({children,variant="primary",disabled=false,onClick,fullWidth=false,compact=false}:ButtonProps){
9	 const palette = variant==="primary"?{background:colors.ink,color:"#fff",borderColor:colors.ink}:variant==="destructive"?{background:"#fff",color:"#ae2d2d",borderColor:"#e4cccc"}:variant==="ghost"?{background:"transparent",color:colors.muted,borderColor:"transparent"}:{background:"#fff",color:colors.ink,borderColor:"#d8d8d8"};
10	 return <button type="button" disabled={disabled} onClick={onClick} style={{...type,...palette,border:variant==="ghost"?"0":"1px solid",borderColor:palette.borderColor,borderRadius:6,padding:compact?"8px 12px":"11px 16px",fontSize:13,fontWeight:550,display:"inline-flex",alignItems:"center",justifyContent:"center",gap:8,cursor:disabled?"default":"pointer",opacity:disabled?.4:1,width:fullWidth?"100%":undefined,whiteSpace:"nowrap"}}>{children}</button>;
11	}
12	interface InputProps { value?:string; onChange?:(value:string)=>void; placeholder?:string; label?:string; }
13	export function VaultSearch({value="",onChange,placeholder="Search credentials",label="Search credentials"}:InputProps){
14	 return <label style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",border:"1px solid #dcdcdc",borderRadius:6,background:"#fff"}}><Search size={16} color="#727272"/><input aria-label={label} value={value} onChange={e=>onChange?.(e.target.value)} placeholder={placeholder} style={{...type,border:0,outline:0,width:"100%",fontSize:13,color:colors.ink,background:"transparent",lineHeight:"20px"}}/>{value&&<button type="button" aria-label="Clear search" onClick={()=>onChange?.("")} style={{padding:0,border:0,background:"none",display:"flex",cursor:"pointer"}}><X size={14} color={colors.muted}/></button>}</label>;
15	}
16	interface FilterProps { label?:string; count?:number; active?:boolean; onClick?:()=>void; touch?:boolean; }
17	export function VaultFilter({label="All",count,active=false,onClick,touch=false}:FilterProps){
18	 return <button type="button" aria-pressed={active} onClick={onClick} style={{...type,fontSize:12,fontWeight:active?600:450,display:"flex",alignItems:"center",justifyContent:"center",gap:6,border:"1px solid",borderColor:active?"#d8d8d8":"transparent",background:active?"#fff":"transparent",color:active?colors.ink:colors.muted,borderRadius:5,padding:touch?"7px 8px":"7px 10px",minHeight:touch?44:undefined,cursor:"pointer",whiteSpace:"nowrap"}}>{label}{count!==undefined&&<span style={{fontSize:11,color:active?"#565656":"#8a8a8a"}}>{count}</span>}</button>;
19	}
20	interface CheckboxProps { checked?:boolean; }
21	export function VaultCheckbox({checked=false}:CheckboxProps){return <span aria-hidden="true" style={{width:17,height:17,display:"flex",alignItems:"center",justifyContent:"center",background:checked?colors.ink:"#fff",border:"1px solid",borderColor:checked?colors.ink:"#c8c8c8",borderRadius:4,flexShrink:0}}>{checked&&<Check size={12} color="#fff" strokeWidth={2.5}/>}</span>;}
22	interface AvatarProps { name?:string; size?:number; }
23	export function VaultAvatar({name="Tanishq Palandurkar",size=32}:AvatarProps){return <div style={{width:size,height:size,borderRadius:"50%",background:"#ece8e3",display:"flex",alignItems:"center",justifyContent:"center",fontSize:Math.round(size*.34),fontWeight:600,color:"#655a4c",flexShrink:0}}>{name.split(" ").map(n=>n[0]).slice(0,2).join("")}</div>;}
24	interface IconButtonProps { label?:string; onClick?:()=>void; children?:React.ReactNode; size?:number; }
25	export function VaultIconButton({label="Close",onClick,children,size=32}:IconButtonProps){return <button type="button" aria-label={label} onClick={onClick} style={{border:0,background:"transparent",color:colors.muted,width:size,height:size,display:"flex",alignItems:"center",justifyContent:"center",borderRadius:6,cursor:"pointer",flexShrink:0}}>{children||<X size={18}/>}</button>;}
